/**
 * Return one page of the actions recorded on the organization's Bots' computers while recording computer actions is on, newest first. Records are kept for actionRecordRetentionDays. Only an administrator of the organization may read them. A missing cursor starts at the newest and nextCursor null ends the list.
 * @summary List recorded computer actions
 */

export const ListComputerActionsParams = zod.object({
  organizationId: zod
    .string()
    .min(1)
    .describe(
      "The organization, by its id or its slug. One the caller is not a member of answers as one that does not exist, `default` included.",
    ),
});

export const listComputerActionsQueryLimitDefault = 50;
export const listComputerActionsQueryLimitMax = 100;

export const listComputerActionsQueryCursorMax = 4096;

export const listComputerActionsQueryCursorRegExp = new RegExp(
  "^[A-Za-z0-9_-]+$",
);

export const ListComputerActionsQueryParams = zod.object({
  limit: zod
    .int()
    .min(1)
    .max(listComputerActionsQueryLimitMax)
    .default(listComputerActionsQueryLimitDefault)
    .describe("Most items in one page."),
  cursor: zod
    .string()
    .min(1)
    .max(listComputerActionsQueryCursorMax)
    .regex(listComputerActionsQueryCursorRegExp)
    .optional()
    .describe(
      "Opaque continuation from the previous page's nextCursor, bound to the organization and the filters that made it. The server only ever issues cursors written in URL-safe base64 (letters, digits, - and _, no padding) and refuses anything else, so the pattern says so. A cursor that fits the pattern can still be refused: one this list never gave out, or one made for another organization or other filters.",
    ),
});

export const listComputerActionsResponseNextCursorMax = 4096;

export const listComputerActionsResponseNextCursorRegExp = new RegExp(
  "^[A-Za-z0-9_-]+$",
);

export const ListComputerActionsResponse = zod.object({
  computerActions: zod
    .array(
      zod.object({
        id: zod.string(),
        surface: zod.enum(["cloud", "local"]),
        botId: zod.string().nullable(),
        toolName: zod.string(),
        command: zod.string(),
        outcome: zod.string(),
        createdAt: zod.iso.datetime({ offset: true }),
      }),
    )
    .describe("Newest first, then by id."),
  nextCursor: zod
    .string()
    .max(listComputerActionsResponseNextCursorMax)
    .regex(listComputerActionsResponseNextCursorRegExp)
    .nullable()
    .describe(
      "Pass as cursor for the next page. Null ends the list. Written in URL-safe base64, the only form the cursor parameter accepts.",
    ),
});

